examples.code:
# Guaranteed: requests == limits for every container
resources:
  requests: { cpu: "500m", memory: "1Gi" }
  limits:   { cpu: "500m", memory: "1Gi" }

# Burstable: requests < limits (or only requests set)
resources:
  requests: { cpu: "100m", memory: "256Mi" }
  limits:   { memory: "1Gi" }

# BestEffort: nothing set - first to be evicted
